from roman import from_roman, _to_roman


class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(from_roman('XIV'), 14)

    def test_valid(self):
        for s, n in [('I', 1), ('IV', 4), ('IX', 9), ('XL', 40), ('XC', 90),
                     ('CD', 400), ('CM', 900), ('MCMXCIV', 1994), ('MMMCMXCIX', 3999)]:
            self.assertEqual(from_roman(s), n, s)

    def test_round_trip_all(self):
        for n in range(1, 4000):
            self.assertEqual(from_roman(_to_roman(n)), n)

    def test_invalid(self):
        for s in ['', 'IIII', 'VX', 'IC', 'MMMM', 'xiv', 'VV', 'IIV', 'IXI',
                  'XM', 'LL', 'DD', 'IL', 'VIV', 'CMC', 'A', 'X I']:
            with self.assertRaises(ValueError, msg=s):
                from_roman(s)

    def test_non_string(self):
        with self.assertRaises(ValueError):
            from_roman(None)


if __name__ == '__main__':
    unittest.main()
